recipes.code:
{
  "inputs": [
    {
      "id": "appfigures-api-key",
      "type": "promptString",
      "description": "Appfigures personal access token. Optional; omit it to sign in with `af auth login` instead. Read more at https://help.appfigures.com/en/article/1chf6wf",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@appfigures/cli@1.0.3",
        "mcp"
      ],
      "env": {
        "APPFIGURES_API_KEY": "${input:appfigures-api-key}"
      }
    }
  }
}
